using static StrataLint.Scribe.DefinitionDsl;
using static StrataLint.Scribe.FormulaDsl;
using F = StrataLint.Scribe.FormulaDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.HomologicalAlgebra.EilenbergZilber;

internal sealed class SpecialContractionShuffleDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Ordered repeats and signed shuffle cancellation", H("Ordered repeats and signed shuffle cancellation"), Blocks(
        Paragraph(Text("All degrees are arbitrary natural numbers. A letter OpLetter(s,n) is a pair of monotone simplex maps [n] → [s]; finite integer sums form DerivedOp(s,n). The convention MTwo.comp MOne applies MOne first after realization. A structural norm is generated by an output diagonal noninjective simplex map, and Moore retraction kills its realization for every bisimplicial object in every abelian category with independent object and morphism universes.")),
        Paragraph(Text("Ordered repeats are the local mechanism: if the horizontal input repeats at j and the vertical input repeats at k with j ≤ k, every split meets one of the two repeats. The corresponding composite h-letter has a common plateau. Factoring both coordinates through that codegeneracy makes the single term a structural norm, and integer sums preserve this property.")),
        Paragraph(Text("For a (p,q)-shuffle and split r, either an offending step gives a common plateau or the shuffle passes through the unique matching staircase corner. Only the matching corner can remain in h after the shuffle. Rectangular paired maps keep p and q separate. The signed decomposition by the first left or right step uses the actual insertion signs, including the p=0 and q=0 axes.")),
        Paragraph(Text("Apply this signed first-step recursion to phiOp(0)=0 and phiOp(n+1)=−(phiOp n).prime+(hOp(n+1)).prime.comp(D0op(n+1)). The nondegenerate corner terms cancel; the remaining terms have a common plateau. Induction in the total degree proves that phi after the signed rectangular shuffle is a rectangular norm. Postcomposing its two simplex coordinates with the front and back inclusions, and summing over p+q=n, gives IsNorm ((phiOp n).comp (hOp n)). This argument includes every degree and both zero axes.")),
        Paragraph(Text("The classical source is Eilenberg–Mac Lane, On the Groups H(Π,n), II, Annals of Mathematics, second series 60 (1954), 49–139, DOI 10.2307/1969702, printed pages 53–55; compare Shih, chapter II, pages 25–26 (running 113–114), and Franz, arXiv:2006.02819v2, footnote 3. Product-chain or quotient conventions in those sources do not by themselves identify the Moore-kernel construction. The paired-map norm calculation here is universal, and SpecialContraction applies its realization with the Moore projector. IsFrontalHom, primeHom_frontal and primeHom_comp_degenZero are received from Jeffrey Li’s LeanPool/EilenbergZilber/BisimplicialDerivedOp.lean at author release fd0147a1ffe4f3c14c247574e148893d7cdf8cf6. The hOp_horizontal_frontal calculation follows locally from the horizontal shuffle summands.")),
        Describe.Lean(DescribeId.Create("ez-specialcontractionshuffle-repeats"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/SpecialContractionShuffle.Repeats"), H("Repeats"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("An adjacent repeat is Repeats f i := f.toOrderHom i.castSucc = f.toOrderHom i.succ, for any n : Nat, a : SimplexCategory, f : [n] → a and i : Fin n. The condition concerns the two vertices bordering the i-th step."))), DescribeRole.Definition),
        Describe.Lean(DescribeId.Create("ez-specialcontractionshuffle-repeats-comp"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/SpecialContractionShuffle.comp"), H("Repeats.comp"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For every n : Nat, a,b : SimplexCategory, f : [n] → a, i : Fin n, h : Repeats f i and g : a → b, Repeats (f ≫ g) i. Postcomposition preserves equality of the adjacent images."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-specialcontractionshuffle-repeats-prime"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/SpecialContractionShuffle.prime"), H("Repeats.prime"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For every s,n : Nat, f : [n] → [s] and i : Fin n, Repeats f i implies Repeats (primeHom f) i.succ. Both adjacent vertices shift by one."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-specialcontractionshuffle-repeats-sigma"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/SpecialContractionShuffle.repeats_sigma"), H("repeats_sigma"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For every n : Nat and i : Fin(n+1), Repeats (SimplexCategory.σ i) i. A codegeneracy identifies precisely this adjacent pair."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-specialcontractionshuffle-hop-comp-ordered-repeat"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/SpecialContractionShuffle.hOp_comp_ordered_repeat"), H("hOp_comp_ordered_repeat"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For every s,n : Nat, l : OpLetter s n, c : Int and j,k : Fin n, if j ≤ k, Repeats l.fst j and Repeats l.snd k, then IsNorm ((hOp n).comp (Finsupp.single l c)). Each split r either lies after j in the first coordinate or at or before k in the second coordinate; a common output repeat then factors through a diagonal codegeneracy."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-specialcontractionshuffle-isfrontalhom"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/SpecialContractionShuffle.IsFrontalHom"), H("IsFrontalHom"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("For every a,b : Nat and f : [a] → [b], IsFrontalHom f means f.toOrderHom 0 = 0. A frontal map fixes the bottom vertex."))), DescribeRole.Definition),
        Describe.Lean(DescribeId.Create("ez-specialcontractionshuffle-hop-horizontal-frontal"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/SpecialContractionShuffle.hOp_horizontal_frontal"), H("hOp_horizontal_frontal"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For every n : Nat, l : OpLetter n n and hl : l ∈ (hOp n).support, IsFrontalHom l.fst. Every supported horizontal map of the Alexander–Whitney–shuffle operator fixes zero. No frontality of the vertical map is asserted."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-specialcontractionshuffle-primehom-frontal"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/SpecialContractionShuffle.primeHom_frontal"), H("primeHom_frontal"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("For every s,q : Nat and θ : [q] → [s], IsFrontalHom (primeHom θ). The prepended bottom vertex is fixed. This simplex-map fact is received from Jeffrey Li’s author release."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-specialcontractionshuffle-primehom-comp-degenzero"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/SpecialContractionShuffle.primeHom_comp_degenZero"), H("primeHom_comp_degenZero"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("For every s,q : Nat, θ : [q] → [s] and hθ : IsFrontalHom θ, primeHom θ ≫ σ(0 : Fin(s+1)) = σ(0 : Fin(q+1)) ≫ θ. At zero the frontality hypothesis equates the two images; at a successor vertex both sides recover θ. This simplex-map fact is received from Jeffrey Li’s author release."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-specialcontractionshuffle-diagletter"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/SpecialContractionShuffle.diagLetter"), H("diagLetter"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For every n : Nat and i : Fin(n+1), diagLetter i : OpLetter n (n+1) is the pair (σ i,σ i). Realization is the corresponding degeneracy of the diagonal simplicial object."))), DescribeRole.Definition),
        Describe.Lean(DescribeId.Create("ez-specialcontractionshuffle-phiop-comp-hop-isnorm"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/SpecialContractionShuffle.phiOp_comp_hOp_isNorm"), H("phiOp_comp_hOp_isNorm"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For every n : Nat, IsNorm ((phiOp n).comp (hOp n)). This is the exact recursive homotopy after the actual Alexander–Whitney–shuffle operator, before realizing on an abelian category."))), DescribeRole.Theorem))));
}
